    "external_pretrain": "pretrain_stage",
    "ddr_finetune": "ddr_finetune_stage",
}
# 控制臂不允许有外部预训练段
CONTROL_ARMS = ("H0", "U0")
MODES = ("formal", "calibration")

# CLI 可覆盖的"校准层"字段（仅 calibration 模式；formal 模式禁止）
CALIBRATION_OVERRIDES = ("micro_batch", "grad_accum", "gradient_checkpointing")

