    路径级的 test 引用由 tools/preflight_contract.py 的 F/G 项负责。
    """
    if str(split).strip().lower() == "test":
        raise GateError(
            f"{role} 不得使用 test split（当前 {split!r}）。"
            "test 仅允许在四项实验全部锁定后做一次最终评估，"
            "绝不参与训练或 checkpoint 选型。"
