def _verify_safely_loadable(path: str) -> None:
    try:
        torch.load(path, map_location="cpu", weights_only=True)
    except Exception as e:
        raise ValueError(
            "checkpoint 写入自检失败：产物无法用 weights_only=True 安全加载"
            f"（{type(e).__name__}: {e}）。"
            "通常是载荷里混入了未归一化的对象（如 TorchVersion / numpy 标量）。"
        ) from e
